insert into public.sample_authors(id,handle,display_name,bio) values
('62c5b85f-d1f8-5f5e-a2de-7eab77823176','nemuri_lab','ねむり計測室','眠気と休日を調べる公式サンプル。実在の利用者ではありません。'),
('7ced12c9-135d-56cc-a169-9539ee33a5e4','kitchen_notes','台所の観察者','台所の小事件を調べる公式サンプル。実在の利用者ではありません。'),
('db53266a-6d71-5232-b35a-0be225fa9f57','train_window','通勤の窓際','移動と待ち合わせを調べる公式サンプル。実在の利用者ではありません。'),
('0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','reply_pending','返信保留中','会話のすれ違いを調べる公式サンプル。実在の利用者ではありません。'),
('4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','math_in_pocket','ポケットの数学','日常の計算違いを調べる公式サンプル。実在の利用者ではありません。'),
('b17da883-163f-500d-b13b-5f5637787e9f','town_margin','まちの余白','街で見つけた疑問を調べる公式サンプル。実在の利用者ではありません。'),
('53380863-84ea-56fa-822b-97a117ce48ef','otaku_shelf','オタクの棚','趣味と時間を調べる公式サンプル。実在の利用者ではありません。'),
('7c500ff1-2e74-5d9b-adb2-bece30919a47','word_collector','言葉の採集者','言葉の妙な働きを調べる公式サンプル。実在の利用者ではありません。'),
('85768e26-eb90-58e2-a832-eac67f594703','object_philosophy','ものの哲学','道具と習慣を調べる公式サンプル。実在の利用者ではありません。'),
('95e7c850-fe1e-5942-9f47-4c59bf813cb0','rainy_statistics','雨の日統計','天気と体感を調べる公式サンプル。実在の利用者ではありません。') on conflict(id) do update set display_name=excluded.display_name,bio=excluded.bio;
insert into public.papers(id,sample_author_id,author,category,title,blocks,tags,created_at) values
('75d7d295-f92b-5fba-8102-2a1714739ec7','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','人間関係','「今向かってる」はどこから向かっているのか','[{"type":"text","heading":"要旨","body":"待ち合わせにおける「今向かってる」は、現在地を報告する文として読まれがちである。しかし送信者は、まだ片方の靴しか履いていない可能性がある。"},{"type":"text","heading":"仮説","body":"「向かう」は移動開始ではなく、外出する意思が生まれた瞬間から成立する、と送信者は考えている。"},{"type":"image","asset":"images/on-my-way.jpg","caption":"この論文のために生成した挿絵"},{"type":"text","heading":"観察方法","body":"玄関を出た時刻ではなく、布団から起きた時刻、靴下を探し始めた時刻、実際に電車に乗った時刻を分けて記録する。本人に送信時刻を聞くと記憶が補正されるため、スマホの送信履歴を使う。"},{"type":"text","heading":"結論","body":"「今向かってる」は位置情報ではない。遅刻しない人格でありたい、という宣言である。なお本研究の筆者も、現在はまだ家にいる。"}]'::jsonb,ARRAY['待ち合わせ','言葉の定義']::text[],now() - interval '0 hours'),
('641474d6-aaf3-5083-af1b-2812c611e1c0','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','暮らし','電子レンジの残り1秒を止める人は何と戦っているのか','[{"type":"text","heading":"研究課題","body":"電子レンジの終了音は危険ではない。それでも残り1秒で停止ボタンを押すと、妙な達成感がある。この勝敗は誰が決めているのか。"},{"type":"text","heading":"仮説","body":"勝利条件は食品の温度ではなく、レンジが先に鳴るか、人間が先に押すかという順序にある。"},{"type":"image","asset":"images/microwave-second.jpg","caption":"この論文のために生成した挿絵"},{"type":"text","heading":"検証案","body":"同じ飲み物を30回温め、停止時刻と満足度を記録する。残り2秒で押した回、終了後に開けた回も比較する。飲み物の味が変わったという主張は測定対象から外す。"},{"type":"text","heading":"考察と結論","body":"仮に満足度だけ上がっても、レンジ側は勝負を認識していない。つまりこれは、人類が一方的に開催し、一方的に優勝している大会である。"}]'::jsonb,ARRAY['電子レンジ','日常の勝負']::text[],now() - interval '1 hours'),
('3a0989ef-5540-5759-beff-6eb00a6bd396','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','「なんでもいい」と言った人が却下できる料理の上限','[{"type":"text","heading":"要旨","body":"夕食を尋ねられて「なんでもいい」と答えた人が、カレー、ラーメン、昨日と同じものを順に却下した。本論文は、この言葉が許す拒否回数を検討する。"},{"type":"text","heading":"仮説","body":"「なんでもいい」は全候補への同意ではない。候補を出す労働を相手に任せつつ、自分の好みを後から発見する方式である。"},{"type":"image","asset":"images/anything-is-fine.jpg","caption":"この論文のために生成した挿絵"},{"type":"text","heading":"検証方法","body":"候補を一品ずつ提示し、却下理由を記録する。「重い」「気分じゃない」「それは昨日食べた」を別々の理由として数える。ただし架空のデータを実測値としては扱わない。"},{"type":"text","heading":"仮結論","body":"却下の上限は料理の数でなく、提案者の忍耐で決まる。「じゃあ君が決めて」と返した瞬間、研究は倫理審査に入る。"}]'::jsonb,ARRAY['献立','会話']::text[],now() - interval '2 hours'),
('07cecb45-1a39-57c0-82ca-0c54b741e343','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','布団に入ってから喉が渇く現象の発生条件','[{"type":"text","heading":"問い","body":"机にいた30分間は平気だったのに、布団へ入った瞬間、水が飲みたくなる。喉は布団を認識できるのか。"},{"type":"text","heading":"仮説","body":"水分不足が突然生じたのではない。立ち上がる費用が高くなったことで、同じ渇きが大事件として観測される。"},{"type":"text","heading":"検証案","body":"寝る直前に水を飲む日と飲まない日を比較し、渇きだけでなく『布団から出たくなさ』も記録する。室温と塩辛い夕食は交絡要因とする。"},{"type":"text","heading":"結論","body":"布団は喉を乾かす装置ではなく、用事の価値を最大化する装置である。歯磨き後のお菓子まで魅力的に見える理由も、おそらく同じである。"}]'::jsonb,ARRAY['睡眠','布団']::text[],now() - interval '3 hours'),
('0b4e9297-5658-54e9-bcc7-fc95781fff86','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','洗濯機の「あと1分」は時間の単位なのか','[{"type":"text","heading":"問題設定","body":"洗濯機に表示された「あと1分」を見てから、湯を沸かし、コップを洗い、再び見ると、まだ「あと1分」だった。"},{"type":"text","heading":"仮説","body":"この1分は時計の60秒ではなく、脱水の偏りが解消するまでの待機状態を表す。したがって表示は予言ではなく願望に近い。"},{"type":"text","heading":"検証案","body":"スマホの時計で表示開始から終了音までを計測する。偏った大物を入れた回と少量の衣類だけの回を比べ、平均だけでなく最長記録も残す。"},{"type":"text","heading":"結論","body":"もし実測が長くても、洗濯機を責める前に衣類の偏りを確認したい。ただし『あと1分』と表示した以上、その間にもう一話見始めた人間にも責任はない。"}]'::jsonb,ARRAY['洗濯','時間']::text[],now() - interval '4 hours'),
('ff65c10a-1657-58b6-8d80-54e4a16befd4','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','エレベーターの「閉」ボタン連打は交渉として成立するか','[{"type":"text","heading":"研究課題","body":"同じボタンを三回押したところで、機械に急ぐ事情が追加で伝わるとは考えにくい。それでも人は押す。"},{"type":"text","heading":"仮説","body":"二回目以降の押下はエレベーターへの命令ではなく、待っている自分への『できることはした』という報告である。"},{"type":"text","heading":"観察案","body":"ドアが閉まり始めるまでの秒数と押下回数を記録する。押さない回も設ける。ただし他の乗客を締め出す操作は実験に含めない。"},{"type":"text","heading":"結論","body":"連打で短縮できるのは待ち時間ではなく、何もしない不安かもしれない。研究者は今朝、五回押して結局乗り遅れた。"}]'::jsonb,ARRAY['エレベーター','通勤']::text[],now() - interval '5 hours'),
('7db574c7-67b0-58f7-94c2-5a7d2de0bd35','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','買い物袋を一度で運ぼうとする人の合理性','[{"type":"text","heading":"要旨","body":"二往復すれば安全なのに、指に袋を六つ掛けて玄関へ向かう人がいる。本人は効率化と呼ぶが、途中で鍵が出せない。"},{"type":"text","heading":"仮説","body":"往復回数を最小にする目的だけを採用した結果、指の痛みと鍵の取り出し時間が計算から消えている。"},{"type":"text","heading":"検証案","body":"一往復と二往復で、車から冷蔵庫までの総時間を比べる。袋の破損と『誰かドア開けて』の回数も費用に入れる。"},{"type":"text","heading":"結論","body":"最短経路を選んだはずの人間が、玄関で袋に囲まれて立ち尽くす。これは数学の失敗ではなく、目的関数の選び方の失敗である。"}]'::jsonb,ARRAY['買い物','効率']::text[],now() - interval '6 hours'),
('bcc09523-00ca-5aa4-8cc8-d2ea96f8710e','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','「あと一話だけ」は停止条件として機能するか','[{"type":"text","heading":"問い","body":"動画を止めるために宣言した「あと一話だけ」が、三話目の冒頭でも有効であり続けるのはなぜか。"},{"type":"text","heading":"仮説","body":"一話を見るたびに『あと一話』が再定義される。数学的には残り話数が1へ戻るため、ゼロに到達しない。"},{"type":"text","heading":"検証案","body":"視聴開始前に就寝時刻を書き、各話の終了時に継続理由を記録する。次回予告と自動再生の有無も残す。なお実験者の睡眠は守る。"},{"type":"text","heading":"結論","body":"「あと一話」は終了予定ではなく、次の一話の開始許可である。真の停止条件は最終話、充電切れ、または翌朝の自分からの苦情だ。"}]'::jsonb,ARRAY['アニメ','夜更かし']::text[],now() - interval '7 hours'),
('a5c76878-d34f-5412-9839-1d1289cdaf94','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','人間関係','「ちょっとだけ聞いて」が長編になる条件','[{"type":"text","heading":"研究課題","body":"「ちょっとだけ聞いて」で始まった相談が、登場人物紹介、過去回想、組織図の説明へ進むことがある。『ちょっと』は何を修飾しているのか。"},{"type":"text","heading":"仮説","body":"短いのは話そのものではなく、聞き手に了承を求める最初の一秒だけである。"},{"type":"text","heading":"検証案","body":"相談の長さと、冒頭で予告された長さを記録する。途中で新たな登場人物が何人増えたかも数える。個人の会話を無断で記録しない。"},{"type":"text","heading":"結論","body":"『ちょっと』は時間の測定値ではなく、会話のドアを開ける小さなノックである。開けた先に三部作がある場合もある。"}]'::jsonb,ARRAY['会話','言葉']::text[],now() - interval '8 hours'),
('18115ff0-8a75-5799-aef2-8c8305cce369','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','傘を持った日に限って雨が降らないという主張の検証','[{"type":"text","heading":"問い","body":"傘を持参すると晴れ、忘れると降る。この規則が本当なら、傘は気象制御装置として国に報告すべきである。"},{"type":"text","heading":"仮説","body":"傘が天気を変えるのではなく、持ってきた日に降らなかった悔しさと、忘れた日に濡れた記憶だけが強く残る。"},{"type":"text","heading":"検証案","body":"一か月間、傘の有無と実際の降雨を毎日記録する。『晴れたから傘を持たなかった日』も忘れず母数に入れる。"},{"type":"text","heading":"結論","body":"記録が予想通りなら、傘を責める根拠はない。ただし、置き傘を買った翌日に晴れる現象だけは、研究者の感情が追いついていない。"}]'::jsonb,ARRAY['雨','確率']::text[],now() - interval '9 hours'),
('4dbca0a0-3c04-5798-b2d1-ee5fe0650b92','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','冷蔵庫を二度開けると新しい食べ物が生まれるのか','[{"type":"text","heading":"要旨","body":"一度目に何もなかった冷蔵庫を、五分後にもう一度開けた。食材の補充はないのに、なぜ二度目を期待したのか。"},{"type":"text","heading":"仮説","body":"探しているのは食材ではなく、『今なら食べたいものがあるかも』という自分の気分の変化である。"},{"type":"text","heading":"検証案","body":"一度目と二度目の中身を写真で比べ、食材ではなく食欲が変わったかを記録する。冷蔵庫を開けたまま考える行為は電気代のため控える。"},{"type":"text","heading":"結論","body":"新しい食べ物は生まれなかった。しかし二度目には、さっき見送ったヨーグルトに希望を見いだした。変化したのは冷蔵庫ではなく、妥協の水準である。"}]'::jsonb,ARRAY['冷蔵庫','夜食']::text[],now() - interval '10 hours'),
('576f6355-2780-5662-9c43-a57e8565410b','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','休日の昼寝を『目を閉じただけ』と呼ぶ理由','[{"type":"text","heading":"問題設定","body":"14時に横になり、16時に起きた人が『寝てない、目を閉じてただけ』と述べた。二時間という記録と本人の証言が一致しない。"},{"type":"text","heading":"仮説","body":"昼寝と認めると、休日を使った事実が確定してしまう。そこで言葉の上では、休憩をまだ開始していないことにする。"},{"type":"text","heading":"検証案","body":"起床後の第一声と時計を見たときの反応を観察する。睡眠計測機器を使う場合も、本人が休日をどう過ごしたいかを優先する。"},{"type":"text","heading":"結論","body":"昼寝の有無は時計で確かめられるが、休日の満足度は時計では決まらない。とはいえ『ちょっと目を閉じた』のちょっとが二時間だった件は記録に残す。"}]'::jsonb,ARRAY['昼寝','休日']::text[],now() - interval '11 hours') on conflict(id) do update set author=excluded.author,category=excluded.category,title=excluded.title,blocks=excluded.blocks,tags=excluded.tags,created_at=excluded.created_at where public.papers.sample_author_id=excluded.sample_author_id;
